import { createInterface } from 'node:readline';
import type {
  AgentEvent,
  AgentMode,
  PermissionRequest,
  PermissionResponse,
  ProviderConfig,
  RpcEnvelope,
  RpcRequest,
  RpcResponse,
} from '@mookacode/protocol';
import { MookaCore } from './core';
import { CancelledError, errorMessage } from './util/errors';
import { redactSecrets } from './util/redact';

const VERSION = '0.1.0';

let core: MookaCore | null = null;
const activeRuns = new Map<string, AbortController>();
const permissionWaiters = new Map<string, { resolve: (response: PermissionResponse) => void; runId: string }>();
let shuttingDown = false;
const pendingRequests = new Set<Promise<void>>();

function send(envelope: RpcEnvelope): void {
  process.stdout.write(`${JSON.stringify(envelope)}\n`);
}

function respond(id: string, result: unknown): void {
  send({ id, result });
}

function respondError(id: string, code: string, message: string, details?: unknown): void {
  send({ id, error: { code, message: redactSecrets(message), details } });
}

function requireCore(): MookaCore {
  if (!core) throw new Error('Worker is not initialized. Call core.init first.');
  return core;
}

function emitEvent(requestId: string, event: AgentEvent): void {
  send({ type: 'event', requestId, event });
}

function permissionBridge(runId: string) {
  return (request: PermissionRequest) =>
    new Promise<PermissionResponse>((resolve) => {
      permissionWaiters.set(request.id, { resolve, runId });
      emitEvent(runId, { type: 'permission.request', request });
    });
}

async function handleAgentRun(request: RpcRequest): Promise<void> {
  const runId = request.id;
  if (activeRuns.size > 0) {
    respondError(runId, 'RUN_ACTIVE', 'Another agent run is already active. Stop it before starting a new one.');
    return;
  }
  const params = (request.params ?? {}) as {
    task?: string;
    mode?: AgentMode;
    provider?: string;
    model?: string;
    sessionId?: string;
    continueSession?: boolean;
    maxIterations?: number;
    preference?: 'quality' | 'balanced' | 'economy';
  };
  const instance = requireCore();
  const controller = new AbortController();
  activeRuns.set(runId, controller);
  try {
    const result = await instance.runAgent(
      {
        task: params.task ?? '',
        mode: params.mode,
        provider: params.provider,
        model: params.model,
        sessionId: params.sessionId,
        continueSession: params.continueSession,
        maxIterations: params.maxIterations,
        preference: params.preference,
        signal: controller.signal,
        requestPermission: permissionBridge(runId),
      },
      (event) => emitEvent(runId, event),
    );
    respond(runId, result);
  } catch (error) {
    const cancelled = error instanceof CancelledError;
    respondError(runId, cancelled ? 'CANCELLED' : 'AGENT_ERROR', errorMessage(error));
  } finally {
    for (const [permissionId, waiter] of permissionWaiters) {
      if (waiter.runId === runId) {
        waiter.resolve({ id: permissionId, approved: false, reason: 'Agent run ended.' });
        permissionWaiters.delete(permissionId);
      }
    }
    activeRuns.delete(runId);
  }
}

async function dispatch(request: RpcRequest): Promise<void> {
  const params = (request.params ?? {}) as Record<string, unknown>;
  switch (request.method) {
    case 'core.init': {
      if (core) {
        respond(request.id, { info: core.info(), alreadyInitialized: true });
        return;
      }
      core = await MookaCore.create({
        cwd: typeof params.cwd === 'string' ? params.cwd : process.cwd(),
        trustProject: typeof params.trustProject === 'boolean' ? params.trustProject : undefined,
      });
      respond(request.id, {
        info: core.info(),
        config: core.snapshot,
        project: await core.projectSnapshot(),
      });
      return;
    }
    case 'core.ping':
      respond(request.id, { ok: true, version: VERSION, pid: process.pid });
      return;
    case 'core.info':
      respond(request.id, requireCore().info());
      return;
    case 'core.reload':
      respond(request.id, await requireCore().reload());
      return;
    case 'core.shutdown':
      respond(request.id, { ok: true });
      await shutdown();
      return;
    case 'config.get':
      respond(request.id, requireCore().snapshot);
      return;
    case 'config.update':
      respond(
        request.id,
        await requireCore().updateConfig(
          (params.patch ?? {}) as Record<string, unknown>,
          params.scope === 'project' ? 'project' : 'global',
        ),
      );
      return;
    case 'config.trust':
      respond(request.id, await requireCore().trustCurrentProject());
      return;
    case 'config.revokeTrust':
      respond(request.id, await requireCore().revokeProjectTrust());
      return;
    case 'providers.list': {
      const instance = requireCore();
      const status = await instance.providers.keyStatus();
      respond(
        request.id,
        instance.config.providers.map((provider) => ({
          ...provider,
          models: undefined,
          modelCount: provider.models.length,
          keySource: provider.type === 'ollama' ? 'local' : (status.get(provider.id) ?? 'none'),
          isDefault: provider.id === instance.config.defaultProvider,
        })),
      );
      return;
    }
    case 'providers.add':
      respond(
        request.id,
        await requireCore().addProvider(params.provider as ProviderConfig, Boolean(params.setDefault)),
      );
      return;
    case 'providers.remove':
      respond(request.id, await requireCore().removeProvider(String(params.providerId)));
      return;
    case 'providers.default':
      respond(
        request.id,
        await requireCore().setDefault(String(params.providerId), params.modelId ? String(params.modelId) : undefined),
      );
      return;
    case 'providers.probe':
      respond(
        request.id,
        await requireCore().probeProvider(
          String(params.providerId),
          params.modelId ? String(params.modelId) : undefined,
        ),
      );
      return;
    case 'models.list':
      respond(request.id, await requireCore().models());
      return;
    case 'auth.list':
      respond(request.id, { backend: await requireCore().authBackend(), entries: await requireCore().authList() });
      return;
    case 'auth.set':
      respond(request.id, {
        backend: await requireCore().setApiKey(String(params.providerId), String(params.apiKey ?? '')),
      });
      return;
    case 'auth.remove':
      respond(request.id, { removed: await requireCore().removeApiKey(String(params.providerId)) });
      return;
    case 'project.info':
      respond(request.id, await requireCore().projectSnapshot());
      return;
    case 'sessions.list':
      respond(request.id, await requireCore().listSessions((params.search ?? {}) as never));
      return;
    case 'sessions.get':
      respond(request.id, await requireCore().getSession(String(params.id)));
      return;
    case 'sessions.rename':
      respond(request.id, await requireCore().renameSession(String(params.id), String(params.title ?? '')));
      return;
    case 'sessions.archive':
      respond(request.id, await requireCore().archiveSession(String(params.id), params.archived !== false));
      return;
    case 'sessions.delete':
      respond(request.id, { removed: await requireCore().deleteSession(String(params.id)) });
      return;
    case 'sessions.latest': {
      const instance = requireCore();
      const latest = await instance.sessionStore.latest(instance.root);
      respond(request.id, latest);
      return;
    }
    case 'git.status':
      respond(request.id, await requireCore().gitStatus());
      return;
    case 'git.diff':
      respond(request.id, {
        diff: await requireCore().gitDiff(
          Array.isArray(params.paths) ? params.paths.map(String) : undefined,
          typeof params.context === 'number' ? params.context : undefined,
        ),
      });
      return;
    case 'git.log':
      respond(request.id, await requireCore().gitLog(Number(params.limit) || 20));
      return;
    case 'git.checkpoint.apply':
      await requireCore().applyCheckpoint(String(params.ref));
      respond(request.id, { ok: true });
      return;
    case 'diagnostics':
      respond(request.id, { results: await requireCore().diagnostics((params.files as string[]) ?? []) });
      return;
    case 'mcp.statuses':
      respond(request.id, { servers: await requireCore().mcpStatuses() });
      return;
    case 'mcp.refresh':
      respond(request.id, { servers: await requireCore().refreshMcp() });
      return;
    case 'lsp.statuses':
      respond(request.id, { servers: await requireCore().lspStatuses() });
      return;
    case 'memory.list': {
      const instance = requireCore();
      respond(request.id, { entries: await instance.memory.load() });
      return;
    }
    case 'memory.remove': {
      const instance = requireCore();
      respond(request.id, { removed: await instance.memory.remove(String(params.id)) });
      return;
    }
    case 'agent.run':
      await handleAgentRun(request);
      return;
    case 'agent.cancel': {
      const runId = String(params.runId ?? params.id ?? '');
      const controller = activeRuns.get(runId);
      if (!controller) {
        respondError(request.id, 'RUN_NOT_FOUND', `No active run with id ${runId}.`);
        return;
      }
      controller.abort();
      for (const [permissionId, waiter] of permissionWaiters) {
        if (waiter.runId === runId) {
          waiter.resolve({ id: permissionId, approved: false, reason: 'Run cancelled by user.' });
          permissionWaiters.delete(permissionId);
        }
      }
      respond(request.id, { ok: true, runId });
      return;
    }
    case 'permission.respond': {
      const id = String(params.id ?? '');
      const waiter = permissionWaiters.get(id);
      if (!waiter) {
        respondError(request.id, 'PERMISSION_NOT_FOUND', `No pending permission request ${id}.`);
        return;
      }
      permissionWaiters.delete(id);
      waiter.resolve({
        id,
        approved: Boolean(params.approved),
        alwaysAllow: Boolean(params.alwaysAllow),
        rememberTool: Boolean(params.rememberTool),
        reason: typeof params.reason === 'string' ? params.reason : undefined,
      });
      respond(request.id, { ok: true });
      return;
    }
    default:
      respondError(request.id, 'METHOD_NOT_FOUND', `Unknown method: ${request.method}`);
  }
}

async function shutdown(): Promise<void> {
  if (shuttingDown) return;
  shuttingDown = true;
  for (const controller of activeRuns.values()) controller.abort();
  for (const [id, waiter] of permissionWaiters) {
    waiter.resolve({ id, approved: false, reason: 'Worker shutting down.' });
  }
  permissionWaiters.clear();
  await core?.close().catch(() => undefined);
  core = null;
  setTimeout(() => process.exit(0), 50).unref();
}

function watchParent(): void {
  const parentPid = Number(process.env.MOOKACODE_PARENT_PID);
  if (!Number.isFinite(parentPid) || parentPid <= 0) return;
  const timer = setInterval(() => {
    try {
      process.kill(parentPid, 0);
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      if (code === 'ESRCH') {
        process.stderr.write('worker: parent process exited; shutting down\n');
        void shutdown();
      }
    }
  }, 3000);
  timer.unref();
}

function installSafetyNet(): void {
  const stderrLog = (...args: unknown[]) => {
    process.stderr.write(
      `${args.map((value) => (typeof value === 'string' ? redactSecrets(value) : String(value))).join(' ')}\n`,
    );
  };
  console.log = stderrLog;
  console.info = stderrLog;
  console.warn = stderrLog;
  process.on('unhandledRejection', (error) => {
    process.stderr.write(`worker unhandled rejection: ${redactSecrets(errorMessage(error))}\n`);
  });
  process.on('uncaughtException', (error) => {
    process.stderr.write(`worker uncaught exception: ${redactSecrets(errorMessage(error))}\n`);
    void shutdown();
  });
  process.on('SIGINT', () => void shutdown());
  process.on('SIGTERM', () => void shutdown());
}

async function main(): Promise<void> {
  installSafetyNet();
  watchParent();
  send({ type: 'ready', pid: process.pid, version: VERSION });
  const rl = createInterface({ input: process.stdin, crlfDelay: Infinity, terminal: false });
  rl.on('line', (line) => {
    if (!line.trim() || shuttingDown) return;
    let request: RpcRequest;
    try {
      request = JSON.parse(line) as RpcRequest;
    } catch {
      process.stderr.write('worker: invalid JSON request\n');
      return;
    }
    if (!request.id || !request.method) {
      process.stderr.write('worker: request requires id and method\n');
      return;
    }
    const task = dispatch(request)
      .catch((error) => {
        respondError(request.id, 'WORKER_ERROR', errorMessage(error));
      })
      .finally(() => {
        pendingRequests.delete(task);
      });
    pendingRequests.add(task);
  });
  rl.on('close', () => {
    void (async () => {
      await Promise.allSettled([...pendingRequests]);
      await shutdown();
    })();
  });
}

void main();
